plugins {
    // Apply the org.jetbrains.kotlin.jvm Plugin to add support for Kotlin.
    alias(libs.plugins.kotlin.jvm)
    // Apply the java-library plugin for API and implementation separation.
    `java-library`
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    implementation(libs.slf4j)

    testRuntimeOnly(libs.logback.classic)
}

testing {
    suites {
        // Configure the built-in test suite
        val test = named<JvmTestSuite>("test") {
            // Use Kotlin Test test framework
            useKotlinTest("2.4.0")
            targets.all {
                // OpenCV.load() calls System.load
                testTask.configure { jvmArgs("--enable-native-access=ALL-UNNAMED") }
            }
        }
    }
}

// Submodule lives at the repository root, not inside :lib
val cmakeSrc = rootProject.layout.projectDirectory.dir("opencv_src")
val cmakeBuild = layout.buildDirectory.dir("opencv_build")

val osName = System.getProperty("os.name").lowercase()
val arch = System.getProperty("os.arch").lowercase()
val libName = if (osName.startsWith("linux")) {
    "libopencv_java500.so"
} else if (osName.startsWith("mac")) {
    "libopencv_java500.dylib"
} else {
    error("$osName not supported")
}
val cmakeBuildArgs = buildList {
    add("-DCMAKE_BUILD_TYPE=Release")

    add("-DBUILD_LIST=core,imgproc,geometry,flann,features,java")
    // One self-contained JNI library with all modules linked in
    addAll(listOf("-DBUILD_SHARED_LIBS=OFF", "-DBUILD_FAT_JAVA_LIB=ON", "-DBUILD_JAVA=ON", "-DOPENCV_JAVA_IGNORE_ANT=ON"))
    addAll(listOf("-DBUILD_TESTS=OFF", "-DBUILD_PERF_TESTS=OFF", "-DBUILD_EXAMPLES=OFF", "-DBUILD_DOCS=OFF", "-DBUILD_opencv_apps=OFF"))
    // Headless: no GUI, no video
    addAll(listOf("GTK", "QT", "WAYLAND", "OPENGL", "VTK", "FFMPEG", "GSTREAMER", "V4L", "1394", "AVFOUNDATION", "OBSENSOR")
        .map { "-DWITH_$it=OFF" })
    // No GPU / accelerators, no downloaded or system binary deps
    addAll(listOf("OPENCL", "CUDA", "VULKAN", "VA", "VA_INTEL", "OPENVINO", "IPP", "ITT", "KLEIDICV",
        "LAPACK", "EIGEN", "PROTOBUF", "FLATBUFFERS", "UNIFONT", "TBB", "OPENMP")
        .map { "-DWITH_$it=OFF" })
    add("-DBUILD_ZLIB=ON") // core still needs zlib; link it statically

    if (osName.startsWith("mac")) {
        add("-DCMAKE_OSX_DEPLOYMENT_TARGET=13.0")
    } else if(osName.startsWith("linux")) {
        // Only glibc needed at runtime; keep bundled symbols private
        add("-DCMAKE_SHARED_LINKER_FLAGS=-static-libstdc++ -static-libgcc -Wl,--exclude-libs,ALL -Wl,-Bsymbolic")
    } else {
        error("$osName not supported")
    }
}

val initSubmoduleTask = tasks.register<Exec>("initSubmodule") {
    description = "Clone the OpenCV submodule (shallow, see .gitmodules) if it is missing"
    // Local val so onlyIf captures a File, not the script object (configuration cache)
    val cmakeLists = cmakeSrc.file("CMakeLists.txt").asFile
    onlyIf("submodule not checked out") { !cmakeLists.isFile }
    workingDir(rootProject.layout.projectDirectory)
    // Explicit --depth: with only `shallow = true`, git fetches the pinned commit with full history
    commandLine("git", "submodule", "update", "--init", "--depth", "1", "--", "opencv_src")
}

val configureCmakeTask = tasks.register<Exec> ("cmakeConfig") {
    description = "Configure CMake config"
    dependsOn(initSubmoduleTask)
    // Local val so doFirst captures a File, not the script object (configuration cache)
    val cmakeLists = cmakeSrc.file("CMakeLists.txt").asFile
    // inputs.files (not inputs.file) so a missing submodule reaches the check below instead of failing validation
    inputs.files(cmakeLists)
    inputs.property("cmakeArgs", cmakeBuildArgs)
    outputs.file(cmakeBuild.map { it.file("CMakeCache.txt") })
    doFirst {
        check(cmakeLists.isFile) {
            "Submodule missing after initSubmodule: run `git submodule update --init --depth 1` manually"
        }
    }
    commandLine(listOf("cmake", "-S", cmakeSrc.asFile, "-B", cmakeBuild.get().asFile) + cmakeBuildArgs)
}

val cmakeBuildTask = tasks.register<Exec>("cmakeBuild") {
    description = "Build CMake"
    dependsOn(configureCmakeTask)
    inputs.files(fileTree(cmakeSrc) { exclude(".git/**", "docs/**", "samples/**", "data/**") })

    outputs.file(cmakeBuild.map { it.file("bin/opencv-500.jar") })
    outputs.file(cmakeBuild.map { it.file("lib/$libName") })
    commandLine("cmake", "--build", cmakeBuild.get().asFile, "--parallel")
}

val opencvNative = cmakeBuild.map { it.file("lib/$libName") }
val opencvJar = cmakeBuild.map { it.file("bin/opencv-500.jar") }

// Resource folder per platform; must match OpenCV.platform()
val platform = (if (osName.startsWith("mac")) "macos" else "linux") + "-" + when (arch) {
    "amd64", "x86_64" -> "x86_64"
    "aarch64", "arm64" -> "aarch64"
    else -> error("$arch not supported")
}

// This platform's build as natives/<platform>/<lib> + opencv-500.jar; CI uploads one per platform
val opencvDistTask = tasks.register<Sync>("opencvDist") {
    description = "Collect this platform's OpenCV native library and Java bindings"
    dependsOn(cmakeBuildTask)
    // Only the JNI library; lib/ also holds the static .a archives it was linked from
    from(opencvNative) { into("natives/$platform") }
    from(opencvJar)
    into(layout.buildDirectory.dir("opencv_dist"))
}

// -PopencvDist=<dir> uses already built dists (e.g. the merged CI artifacts) instead of running CMake,
// so the jar gets natives for every platform found there
val opencvDist: FileCollection = providers.gradleProperty("opencvDist")
    .map { files(rootProject.file(it)) }
    .getOrElse(files(opencvDistTask))

tasks.processResources {
    // As a resource so both tests and the jar see it
    from(opencvDist) { include("natives/**") }
}

dependencies {
    // Compile against the generated Java bindings
    api(opencvDist.asFileTree.matching { include("opencv-500.jar") })
}
// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}
